// p2_isp_setup: the ISP's per-primitive, per-tile setup as a microprogrammed unit (PLAN M4; ARCHITECTURE 3.4.4; isp 6,
// 7, 8.1-8.3, 8.6, 9.1-9.5 at refsw3 4f3efe15). It takes an assembled primitive in a tile (the asm stream, p2_asm_t),
// runs its class's program (TRI, QUAD, MODIFIER TRI: rtl/v1/pkg/p2_isp_prog_pkg.sv, GENERATED by
// tools/gen/gen_setup_prog.cpp from the operation graphs of refsw3's arithmetic) on p2_isp_alu, and in the program's
// last step writes the descriptor p2_rdesc_t into the 1-deep hand-off to the rasterizer (p2_isp_raster).
//
// The accept (asm_v && asm_rdy) loads the ALU's input registers: the corners as FromBits (the edge unit, num H4) and the
// first three as FromSingle(., ranged) (the depth unit), the tile's first sample point FromHalves(2 left +
// HALF_OFFSET[0]) on both axes (refsw_tile.cpp L797-798, L809-813), OneThird; and the primitive's own fields. Step 0 of
// the program is the clock after the accept. Every step issues its micro-word; nothing stalls inside a program.
//
// The hand-off step (the program's last, P2_ISP_LEN_<class> - 1) reads the ALU's registers and makes the descriptor
// with the fixed logic of M2 / M3 (one copy, shared with p2_isp_edge_setup and p2_isp_depth_setup):
//   the winding and the culls from the swamped determinant (detE)               p2_fp_cull (num H9; isp 7.2)
//   per edge the steps (p2_isp_edge_steps) and the blocking (p2_isp_edge_fin)   isp 8.3, 8.5
//   the row range and its tile (p2_isp_rowrange, p2_isp_rowclip; MODIFIER 0 .. 31)                  isp 8.6
//   the depth regime and fields (p2_isp_depth_fin; the mean's key flat(mean))   isp 9.3-9.5
//   tag, rm, DepthMode (ISP word 31:29), ZWriteDis (26), quad; sum_op from a MODIFIER's VolumeMode 1 (OR) / 2 (AND)
//
// Cycle [M tim 3.2; I the structure]:
//   - a primitive takes its program's length (the scheduler's: TRI 16, QUAD 18, MODIFIER TRI 16 at the ARCHITECTURE 6
//     parameters; measured 16 a triangle, 19 a sprite);
//   - a culled or bad primitive skips the hand-off step: its program ends one step early (measured 15.05 - 15.1), the
//     cull's verdict being readable in the step before (the generator checks it). Everything is computed all the same;
//   - a MODIFIER triangle with VolumeMode 1 or 2 (a volume's closing triangle) that is culled or has a bad corner is
//     still handed over, with kill and its sum_op, all 32 rows, so that the raster applies the summary
//     (ARCHITECTURE 3.4.4 step 8);
//   - the hand-off holds HO_N = 1 descriptor (ARCHITECTURE 3.4.5 [I tim 3.2]: a triangle costs max(setup, rows)); a
//     program whose hand-off step finds it full waits in that step (no other step stalls), and the next primitive is
//     accepted in the clock its hand-off is written.
// The ptc strobe (pc_v, ARCHITECTURE 3.4.10): per primitive at its program's end, culled (a bad corner counts as stored,
// not culled: isp 11.4) and quad.
module p2_isp_setup
  import p2_hw_pkg::*;
  import p2_pkg::*;
  import p2_fp_pkg::*;
  import p2_regs_pkg::*;
  import p2_isp_prog_pkg::*;
(
  input  logic                         clk,
  input  logic                         rst,
  // the asm stream (p2_isp_pfetch), valid/ready
  input  logic                         asm_v,
  output logic                         asm_rdy,
  input  p2_asm_t                      asm_i,
  // the render's registers
  input  logic [31:0]                  fpu_cull_val,   // FPU_CULL_VAL
  input  logic [31:0]                  fpu_perp_val,   // FPU_PERP_VAL
  input  logic                         half,           // HALF_OFFSET[0] (fpu_pixel_half_offset)
  // the hand-off to p2_isp_raster, valid/ready
  output logic                         rd_v,
  input  logic                         rd_rdy,
  output p2_rdesc_t                    rd,
  // to p2_isp_ptc: per primitive, at its program's end
  output logic                         pc_v,
  output logic                         pc_culled,
  output logic                         pc_quad,
  // no primitive in the program and none in the hand-off (p2_isp_ctl's walk end, M6)
  output logic                         idle,
  // taps (the testbench's program trace; not a hardware interface)
  output logic                         t_issue,        // a program step executes this clock
  output logic [1:0]                   t_cls,
  output logic [P2_ISP_PC_BITS-1:0]    t_pc,
  output p2_isp_uword_t                t_uw,           // the micro-word it issues
  output logic [P2_ISP_NM+P2_ISP_NA:0]                  t_wv,
  output logic [P2_ISP_NM+P2_ISP_NA:0][P2_ISP_RW-1:0]   t_wrd
);
  localparam int HO_N = 1;     // the hand-off's depth [I tim 3.2: max(setup, rows)]
  localparam int RW   = 42;    // row numbers (p2_isp_rowrange)

  // ---------------------------------------------------------------------------------------------- the program
  logic                      act;
  logic [1:0]                cls;
  logic [P2_ISP_PC_BITS-1:0] pc, len;
  // the primitive's own fields (its corners are in the ALU's input registers)
  struct packed {
    logic [31:0] isp;
    p2_tag_t     tag;
    p2_rm_t      rm;
    logic        quad;
    logic [5:0]  tiley;
  } pr;
  logic [3:0]                cbad_x, cbad_y; // FromBits `bad` of each corner's x, y

  logic ho_full, ho_push, ho_pop;
  logic s_skip, s_hand, adv, done, take;
  logic culled, bad, flip, kill_d, modvol;
  p2_sum_op_t sum_op;

  // the step: the hand-off step waits while the hand-off is full; a culled or bad primitive (no kill) ends in the step
  // before it
  assign s_hand  = act && pc == len - P2_ISP_PC_BITS'(1);
  assign s_skip  = act && pc == len - P2_ISP_PC_BITS'(2) && (bad || culled) && !kill_d;
  assign ho_push = s_hand && (!ho_full || ho_pop);
  assign adv     = act && (!s_hand || ho_push);
  assign done    = s_skip || ho_push;
  assign asm_rdy = !act || done;
  assign take    = asm_v && asm_rdy;

  // the input registers at the accept
  p2_fp24_t [P2_ISP_NIN-1:0] ld_val;
  logic [2:0][22:0]          ld_frac;
  logic [3:0]                ld_bx, ld_by;
  p2_fp24_t [3:0]            ex, ey;
  p2_fp24_t [2:0]            zx, zy, zz;
  genvar g;
  generate
    for (g = 0; g < 4; g = g + 1) begin : g_ein
      p2_fp_in_single u_x (.u(asm_i.x[g]), .ranged(1'b0), .o_neg(ex[g].neg), .o_bad(ex[g].bad), .o_exp(ex[g].exp),
        .o_mant(ex[g].mant));
      p2_fp_in_single u_y (.u(asm_i.y[g]), .ranged(1'b0), .o_neg(ey[g].neg), .o_bad(ey[g].bad), .o_exp(ey[g].exp),
        .o_mant(ey[g].mant));
      assign ld_bx[g] = ex[g].bad;
      assign ld_by[g] = ey[g].bad;
    end
    for (g = 0; g < 3; g = g + 1) begin : g_zin
      p2_fp_in_single u_x (.u(asm_i.x[g]), .ranged(1'b1), .o_neg(zx[g].neg), .o_bad(zx[g].bad), .o_exp(zx[g].exp),
        .o_mant(zx[g].mant));
      p2_fp_in_single u_y (.u(asm_i.y[g]), .ranged(1'b1), .o_neg(zy[g].neg), .o_bad(zy[g].bad), .o_exp(zy[g].exp),
        .o_mant(zy[g].mant));
      p2_fp_in_single u_z (.u(asm_i.z[g]), .ranged(1'b1), .o_neg(zz[g].neg), .o_bad(zz[g].bad), .o_exp(zz[g].exp),
        .o_mant(zz[g].mant));
      // a depth of exponent field 255 adds in the mean as its fraction says (pvr_isp_depth.h L647)
      assign ld_frac[g] = (asm_i.z[g][30:23] == 8'hFF) ? asm_i.z[g][22:0] : 23'd0;
    end
  endgenerate

  always_comb begin
    p2_fp24_t t;
    ld_val = '0;
    ld_val[P2_ISP_R_EX0] = ex[0];
    ld_val[P2_ISP_R_EX1] = ex[1];
    ld_val[P2_ISP_R_EX2] = ex[2];
    ld_val[P2_ISP_R_EX3] = ex[3];
    ld_val[P2_ISP_R_EY0] = ey[0];
    ld_val[P2_ISP_R_EY1] = ey[1];
    ld_val[P2_ISP_R_EY2] = ey[2];
    ld_val[P2_ISP_R_EY3] = ey[3];
    ld_val[P2_ISP_R_ZX0] = zx[0];
    ld_val[P2_ISP_R_ZX1] = zx[1];
    ld_val[P2_ISP_R_ZX2] = zx[2];
    ld_val[P2_ISP_R_ZY0] = zy[0];
    ld_val[P2_ISP_R_ZY1] = zy[1];
    ld_val[P2_ISP_R_ZY2] = zy[2];
    ld_val[P2_ISP_R_ZZ0] = zz[0];
    ld_val[P2_ISP_R_ZZ1] = zz[1];
    ld_val[P2_ISP_R_ZZ2] = zz[2];
    // the tile's first sample point in half pixels, 2 left + HALF_OFFSET[0]: FromHalves(k) = {0, 0, -1, k}
    t      = '0;
    t.exp  = P2_FP_EW'(0) - P2_FP_EW'(1);
    t.mant = P2_FP24_MANT_BITS'({asm_i.tilex, {P2_TILE_LOG2{1'b0}}, half});
    ld_val[P2_ISP_R_TX] = t;
    t.mant = P2_FP24_MANT_BITS'({asm_i.tiley, {P2_TILE_LOG2{1'b0}}, half});
    ld_val[P2_ISP_R_TY] = t;
    // OneThird: 1/3 rounded up to 24 bits, 0xAAAAAB 2^-25 (pvr_softfp.h OneThird; perpmean_word: 0xAAAAAA misses 1,618)
    t      = '0;
    t.exp  = P2_FP_EW'(0) - P2_FP_EW'(25);
    t.mant = 24'hAAAAAB;
    ld_val[P2_ISP_R_THIRD] = t;
  end

  // the class: a quad array's primitive, a modifier volume's triangle, any other triangle
  logic [1:0]                in_cls;
  logic [P2_ISP_PC_BITS-1:0] in_len;
  always_comb begin
    if (asm_i.quad) begin
      in_cls = P2_ISP_CLS_QUAD;
      in_len = P2_ISP_PC_BITS'(P2_ISP_LEN_QUAD);
    end else if (asm_i.rm == P2_RM_MODIFIER) begin
      in_cls = P2_ISP_CLS_MOD;
      in_len = P2_ISP_PC_BITS'(P2_ISP_LEN_MOD);
    end else begin
      in_cls = P2_ISP_CLS_TRI;
      in_len = P2_ISP_PC_BITS'(P2_ISP_LEN_TRI);
    end
  end

  // the render's registers as the primitive's accept found them (they are constant over a render; a register write
  // between two primitives takes effect at a primitive's boundary)
  logic [31:0] cull_val_q, perp_val_q;
  logic        half_q;
  logic [2:0][22:0] frac;
  always_ff @(posedge clk) begin
    if (rst) begin
      act <= 1'b0;
    end else begin
      if (adv)
        pc <= pc + P2_ISP_PC_BITS'(1);
      if (done)
        act <= 1'b0;
      if (take) begin
        act <= 1'b1;
        pc  <= '0;
      end
    end
    if (take) begin
      cls    <= in_cls;
      len    <= in_len;
      pr.isp   <= asm_i.isp;
      pr.tag   <= asm_i.tag;
      pr.rm    <= asm_i.rm;
      pr.quad  <= asm_i.quad;
      pr.tiley <= asm_i.tiley;
      cbad_x <= ld_bx;
      cbad_y <= ld_by;
      frac   <= ld_frac;
      cull_val_q <= fpu_cull_val;
      perp_val_q <= fpu_perp_val;
      half_q     <= half;
    end
  end

  // ---------------------------------------------------------------------------------------------- the ALU
  p2_isp_uword_t             uw;
  p2_fp24_t [P2_ISP_NREG-1:0] rf;
  logic                      issue;
  assign issue = act && adv;
  assign uw    = issue ? p2_isp_prog(cls, pc) : '0;
  p2_isp_alu u_alu (.clk(clk), .rst(rst), .issue(issue), .uw(uw), .ld(take), .ld_val(ld_val), .fpu_perp_val(perp_val_q),
    .frac(frac), .rf(rf), .t_wv(t_wv), .t_wrd(t_wrd));

  // ---------------------------------------------------------------------------------------------- the fixed logic
  // the bad corners: any x, y of corners 1-3, or of corner 4 of a quad, an infinity or a NaN (FromBits `bad`;
  // refsw_tile.cpp L780-786, pvr_isp_edge.h Winding): nothing drawn, nothing culled (dreamcast-tests pvr-tests/huge)
  assign bad = (|cbad_x[2:0]) | (|cbad_y[2:0]) | (pr.quad & (cbad_x[3] | cbad_y[3]));

  // the winding and the culls on the swamped determinant (EdgeWinding; CulledBySize / CulledByFacing, num H9)
  // [faredge_m131, faredge_cull 1,200 / 1,200; covmeas rule 9: a zero counts as positive; raster page 4: equal culled]
  p2_fp24_t dete;
  logic     by_size, by_facing;
  assign dete = rf[P2_ISP_R_DETE];
  assign flip = !(dete.neg && dete.mant != '0);
  p2_fp_cull u_cull (.det_neg(dete.neg), .det_bad(dete.bad), .det_exp(dete.exp), .det_mant(dete.mant),
    .fpu_cull_val(cull_val_q), .cull_mode(pr.isp[28:27]), .by_size(by_size), .by_facing(by_facing));
  assign culled = (pr.isp[28:27] != 2'd0) && !bad && (by_size || by_facing);

  // a modifier volume's triangle: its VolumeMode (ISP word 31:29) 1 or 2 closes a volume (isp 15 #16: 3 .. 7 none)
  assign modvol = pr.rm == P2_RM_MODIFIER;
  always_comb begin
    sum_op = P2_SUM_NONE;
    if (modvol && pr.isp[31:29] == 3'd1)
      sum_op = P2_SUM_OR;
    else if (modvol && pr.isp[31:29] == 3'd2)
      sum_op = P2_SUM_AND;
  end
  // the summary-only descriptor (ARCHITECTURE 3.4.4 step 8)
  assign kill_d = (bad || culled) && sum_op != P2_SUM_NONE;

  // the edges: E12, E23, E31 (3 -> 1, or 3 -> 4 for a quad), E41 (quads; a triangle's fourth is inside everywhere)
  p2_fp24_t [3:0] r_dx, r_dy, r_start;
  assign r_dx    = {rf[P2_ISP_R_DX3], rf[P2_ISP_R_DX2], rf[P2_ISP_R_DX1], rf[P2_ISP_R_DX0]};
  assign r_dy    = {rf[P2_ISP_R_DY3], rf[P2_ISP_R_DY2], rf[P2_ISP_R_DY1], rf[P2_ISP_R_DY0]};
  assign r_start = {rf[P2_ISP_R_START3], rf[P2_ISP_R_START2], rf[P2_ISP_R_START1], rf[P2_ISP_R_START0]};
  p2_edge_t [3:0] h_e;
  logic [3:0]     h_big;
  generate
    for (g = 0; g < 4; g = g + 1) begin : g_edge
      localparam int A = g;
      localparam int B = (g + 1) % 4;
      p2_fp20_t                   sx, sy;
      logic signed [P2_FP_XW-1:0] ep;
      logic                       ep_v, ebad;
      p2_edge_t                   e;
      p2_isp_edge_steps u_steps (.dx(r_dx[g]), .dy(r_dy[g]), .sx(sx), .sy(sy), .ep(ep), .ep_v(ep_v));
      // Setup's first test: a bad coordinate of the edge's corners (unreachable behind the bad corner)
      if (g == 2) begin : g_third
        assign ebad = cbad_x[2] | cbad_y[2] | (pr.quad ? (cbad_x[3] | cbad_y[3]) : (cbad_x[0] | cbad_y[0]));
      end else begin : g_other
        assign ebad = cbad_x[A] | cbad_y[A] | cbad_x[B] | cbad_y[B];
      end
      p2_isp_edge_fin u_fin (.start(r_start[g]), .sx(sx), .sy(sy), .ep(ep), .ep_v(ep_v), .bad(ebad), .flip(flip), .e(e));
      assign h_big[g] = ep >= P2_FP_XW'(124);
      if (g == 3) begin : g_fourth
        always_comb begin
          h_e[g] = e;
          if (!pr.quad) begin
            h_e[g].const_v  = 1'b1;
            h_e[g].const_in = 1'b1;
          end
        end
      end else begin : g_e
        assign h_e[g] = e;
      end
    end
  endgenerate

  // the rows (RowRange over the corners' FromBits y; the tile, the row-31 shift; MODIFIER all 32)
  logic signed [RW-1:0]    rfirst, rlast;
  logic [P2_TILE_LOG2-1:0] h_jf, h_jl;
  logic                    h_rows_v;
  p2_isp_rowrange #(.RW(RW)) u_rows (.y({rf[P2_ISP_R_EY3], rf[P2_ISP_R_EY2], rf[P2_ISP_R_EY1], rf[P2_ISP_R_EY0]}),
    .quad(pr.quad), .row_first(rfirst), .row_last(rlast));
  p2_isp_rowclip #(.RW(RW)) u_clip (.row_first(rfirst), .row_last(rlast), .tile_y(pr.tiley), .modvol(modvol),
    .big_any(h_big[0] | h_big[1] | h_big[2] | (pr.quad & h_big[3])), .jf(h_jf), .jl(h_jl), .rows_v(h_rows_v));

  // the depth
  p2_ztile_t h_z;
  p2_isp_depth_fin u_zfin (.a(rf[P2_ISP_R_ZA]), .b(rf[P2_ISP_R_ZB]), .c(rf[P2_ISP_R_ZC]), .det(rf[P2_ISP_R_DETZ]),
    .mean_key(p2_zword_pkg::flat(rf[P2_ISP_R_ZMEAN])), .first0(rf[P2_ISP_R_ZFIRST0]), .a_raw(rf[P2_ISP_R_ARAW]),
    .b_raw(rf[P2_ISP_R_BRAW]), .half(half_q), .z(h_z), .sa_o(), .sb_o());

  p2_rdesc_t h_rd;
  always_comb begin
    h_rd            = '0;
    h_rd.tag        = pr.tag;
    h_rd.rm         = pr.rm;
    h_rd.depth_mode = pr.isp[31:29];
    h_rd.zwdis      = pr.isp[26];
    h_rd.quad       = pr.quad;
    h_rd.sum_op     = sum_op;
    h_rd.kill       = kill_d;
    h_rd.edges      = h_e;
    h_rd.jf         = h_jf;
    h_rd.jl         = h_jl;
    h_rd.rows_v     = h_rows_v;
    h_rd.z          = h_z;
    if (kill_d) begin
      // every row, nothing inside (the raster forces the mask to 0)
      h_rd.jf     = '0;
      h_rd.jl     = '1;
      h_rd.rows_v = 1'b1;
    end
  end

  // ---------------------------------------------------------------------------------------------- the hand-off
  p2_rdesc_t [HO_N-1:0] ho_q;
  localparam int HW = $clog2(HO_N + 1);
  logic [HW-1:0] ho_n;
  assign ho_full = ho_n == HW'(HO_N);
  assign ho_pop  = rd_v && rd_rdy;
  assign rd_v    = ho_n != '0;
  assign rd      = ho_q[0];
  always_ff @(posedge clk) begin
    if (rst) begin
      ho_n <= '0;
    end else begin
      if (ho_pop)
        for (int k = 0; k < HO_N - 1; k++)
          ho_q[k] <= ho_q[k + 1];
      if (ho_push)
        ho_q[ho_pop ? int'(ho_n) - 1 : int'(ho_n)] <= h_rd;
      ho_n <= HW'(ho_n + HW'(ho_push) - HW'(ho_pop));
    end
  end

  // ---------------------------------------------------------------------------------------------- ptc, taps
  assign idle      = !act && ho_n == '0;
  assign pc_v      = done;
  assign pc_culled = culled;
  assign pc_quad   = pr.quad;

  assign t_issue = issue;
  assign t_cls   = cls;
  assign t_pc    = pc;
  assign t_uw    = uw;
endmodule
